mapper.select:
SELECT
s.*,
su.nickname AS leaderName,    
a.name AS areaName            
FROM station_info s
LEFT JOIN station_user su ON s.user_id = su.id AND su.deleted = 0
LEFT JOIN area_info a ON s.area_id = a.id AND a.deleted = 0
WHERE s.deleted = 0


    AND s.id = #{pageReqVO.id}


    AND s.station_no LIKE CONCAT('%', #{pageReqVO.stationNo}, '%')


    AND s.name LIKE CONCAT('%', #{pageReqVO.name}, '%')


    AND s.type = #{pageReqVO.type}


    AND s.address LIKE CONCAT('%', #{pageReqVO.address}, '%')


    AND s.space_total = #{pageReqVO.spaceTotal}


    AND s.user_id = #{pageReqVO.userId}


    AND s.fee_standard = #{pageReqVO.feeStandard}


    AND s.area_id = #{pageReqVO.areaId}


    AND s.operate_type = #{pageReqVO.operateType}


    AND s.status = #{pageReqVO.status}


    AND s.bind_time BETWEEN #{pageReqVO.bindTime[0]} AND #{pageReqVO.bindTime[1]}


    AND s.bind_user_id = #{pageReqVO.bindUserId}


    AND s.device_count = #{pageReqVO.deviceCount}


    AND s.space_count = #{pageReqVO.spaceCount}


    AND s.remark = #{pageReqVO.remark}


    AND s.reserve1 = #{pageReqVO.reserve1}


    AND s.reserve2 = #{pageReqVO.reserve2}


    AND s.create_time BETWEEN #{pageReqVO.createTime[0]} AND #{pageReqVO.createTime[1]}


ORDER BY s.id DESC
